    def walk(o, path=''):
        if isinstance(o, dict):
            for k, v in o.items():
                if k == 'data':
                    print(path + '.data ->', type(v).__name__ if not isinstance(v, dict) else list(v.keys()))
                walk(v, path + '.' + k)
        elif isinstance(o, list):
            for i, v in enumerate(o):
                walk(v, path + f'[{i}]')
    walk(spec)
    print('---')
    print('Top-level keys:', list(spec.keys()))
    print('Has datasets:', 'datasets' in spec)
